using LibraryManagement.Application.DTOs;using LibraryManagement.Application.Services.Base;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace LibraryManagement.Controllers;[Authorize]public class CategoriesController(ICategoryService service):Controller{public async Task<IActionResult>Index()=>View(await service.GetAllAsync());public async Task<IActionResult>Details(string uuid){var x=await service.GetDetailsAsync(uuid);return x is null?NotFound():View(x);}[HttpGet]public IActionResult Create()=>View(new CategoryCreateDto());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(CategoryCreateDto dto){if(!ModelState.IsValid)return View(dto);await service.AddAsync(dto);return RedirectToAction(nameof(Index));}[HttpGet]public async Task<IActionResult>Edit(string uuid){var x=await service.GetForUpdateAsync(uuid);return x is null?NotFound():View(x);}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(CategoryUpdateDto dto){if(!ModelState.IsValid)return View(dto);await service.UpdateAsync(dto);return RedirectToAction(nameof(Index));}[HttpGet]public async Task<IActionResult>Delete(string uuid){var x=await service.GetDetailsAsync(uuid);return x is null?NotFound():View(x);}[HttpPost,ActionName("Delete"),ValidateAntiForgeryToken]public async Task<IActionResult>DeleteConfirmed(string uuid){var x=await service.GetDetailsAsync(uuid);if(x is null)return NotFound();try{await service.DeleteAsync(uuid);return RedirectToAction(nameof(Index));}catch(InvalidOperationException e){ModelState.AddModelError("",e.Message);return View("Delete",x);}}}
